import{_ as i,o as e,c as r,a2 as a}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"終止遊玩契約與上訴","description":"有關於本伺服的遊玩契約終止與上訴。","frontmatter":{"title":"終止遊玩契約與上訴","description":"有關於本伺服的遊玩契約終止與上訴。"},"headers":[],"relativePath":"rule/punish/index.md","filePath":"rule/punish.md"}'),o={name:"rule/punish/index.md"};function t(u,l,n,s,h,c){return e(),r("div",null,[...l[0]||(l[0]=[a('<h1 id="終止遊玩契約與上訴" tabindex="-1">終止遊玩契約與上訴 <a class="header-anchor" href="#終止遊玩契約與上訴" aria-label="Permalink to &quot;終止遊玩契約與上訴&quot;">​</a></h1><h2 id="終止遊玩契約" tabindex="-1">終止遊玩契約 <a class="header-anchor" href="#終止遊玩契約" aria-label="Permalink to &quot;終止遊玩契約&quot;">​</a></h2><ul><li>違反上述<a href="/rule/">伺服規範</a>，伺服人員有權利取消提供下列服務給玩家 <ul><li>暫時限制玩家在遊戲聊天室發言的權利</li><li>暫時或永久限制用戶在Discord發言/加入的權利</li><li>暫時或永久停止玩家在本伺服的遊玩權限</li><li>刪除或回溯玩家在本伺服的遊玩紀錄</li><li>刪除違反規定之相關發言紀錄</li></ul></li><li>因應案件處理之必要，伺服人員得做出下列臨時處置 <ul><li>暫時以臨時領地保護案件現場</li><li>暫時停止玩家在本伺服的遊玩權限，並要求回覆<a href="/discord/customer_service/">客服</a>訊息</li></ul></li><li>未明載但屬伺服規範所涵蓋之事項，將由伺服人員認定及處置</li><li>若玩家知悉上述之情事發生，請即時利用<a href="/discord/customer_service/">客服系統</a>通報，切勿知情不報 <ul><li>知情不報者經伺服人員查獲時將一併進行處理</li></ul></li></ul><h2 id="案件調解" tabindex="-1">案件調解 <a class="header-anchor" href="#案件調解" aria-label="Permalink to &quot;案件調解&quot;">​</a></h2><ul><li>主要適用於『玩家與玩家之間的檢舉』</li><li>主要由<font color="dark_red">被檢舉人</font>親自向<font color="blue">檢舉人</font>提出，伺服方不會主動介入 <ul><li><font color="dark_red">被檢舉人</font>也可由<a href="/discord/customer_service/">客服</a>告知伺服人員，請伺服人員作為第三方協助處理</li></ul></li><li>調解期限 : <font color="blue">檢舉人</font>提出檢舉後，檢舉『還原完成』前 <ul><li>若在還原完成後才提出調解，需由伺服人員同意才可受理</li></ul></li><li>調解流程 <ul><li>若玩家在檢舉後，<font color="dark_red">被檢舉人</font>主動聯繫<font color="blue">檢舉人</font>相關調解事宜，可暫緩檢舉處理 <ul><li><font color="blue">檢舉人</font>有拒絕調解的權力</li></ul></li><li>請<font color="blue">檢舉人</font>在檢舉頻道告知伺服人員此檢舉在調解中</li><li>由雙方自行私下調解(或由伺服人員協助雙方)相關補償或處理方式</li><li>若調解成功，該檢舉將可撤銷，視為此案件未曾發生過</li></ul></li></ul><h2 id="案件上訴" tabindex="-1">案件上訴 <a class="header-anchor" href="#案件上訴" aria-label="Permalink to &quot;案件上訴&quot;">​</a></h2><ul><li>玩家權利上訴 <ul><li>玩家可在判決確定後由<a href="/discord/customer_service/">客服</a>詢問/調解/上訴 <ul><li>上訴期限 : 原則上為判決確定後一個月內</li></ul></li></ul></li><li>解約原因所依據的資料 <ul><li>資料係指:解約依據與解釋判決 <ul><li>帶有個人隱私之內容需消去處理<br> (例如:IP / 座標 / 私人檢舉...)</li></ul></li><li>當事人有權利詢問與要求伺服人員提供資料<br> 而伺服人員有義務回覆並向當事人提供與解釋</li><li>雙方皆有權利向全體玩家公開資料以接受公評</li></ul></li></ul><h2 id="規定歷史紀錄" tabindex="-1">規定歷史紀錄 <a class="header-anchor" href="#規定歷史紀錄" aria-label="Permalink to &quot;規定歷史紀錄&quot;">​</a></h2><ul><li><a href="/rule/history/20220627/">2022-06-27</a></li><li><a href="/rule/history/20211213/">2021-12-13</a></li><li><a href="/rule/history/20211125/">2021-11-25</a></li><li><a href="/rule/history/20211024/">2021-10-24</a></li><li><a href="/rule/history/20210821/">2021-08-21</a></li><li><a href="/rule/history/20210731/">2021-07-31</a></li><li><a href="/rule/history/20200815/">2020-08-15</a></li></ul>',9)])])}const _=i(o,[["render",t]]);export{f as __pageData,_ as default};
